def jump(nums):
    n = len(nums)
    dp = [float('inf')] * n
    dp[0] = 0
    for i in range(1, n):
        for j in range(i):                                     # check every earlier index that could reach i
            if j + nums[j] >= i:
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[n - 1]


if __name__ == "__main__":
    nums = [2, 3, 1, 1, 4]
    print(jump(nums))

