public class Main {
    int jump(int[] nums) {
        int n = nums.length;
        int jumps = 0;
        int currentBoundary = 0;
        int farthest = 0;
        for (int i = 0; i < n - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);                  // farthest reachable from within this level
            if (i == currentBoundary) {
                jumps++;                                                    // this level is exhausted, take a jump
                currentBoundary = farthest;
            }
        }
        return jumps;
    }

    public static void main(String[] args) {
        int[] nums = {2, 3, 1, 1, 4};
        Main solution = new Main();
        System.out.println(solution.jump(nums));
    }
}

